START TRANSACTION;
ALTER TABLE users ADD COLUMN IF NOT EXISTS must_change_password TINYINT(1) NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS locked_until DATETIME NULL;
CREATE TABLE IF NOT EXISTS system_feature_flags (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,key_name VARCHAR(120) NOT NULL UNIQUE,name VARCHAR(180) NOT NULL,description TEXT NULL,enabled TINYINT(1) NOT NULL DEFAULT 0,environment VARCHAR(30) NOT NULL DEFAULT 'all',rollout_percentage DECIMAL(5,2) NOT NULL DEFAULT 100,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS system_modules (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,module_key VARCHAR(120) NOT NULL UNIQUE,name VARCHAR(180) NOT NULL,description TEXT NULL,enabled TINYINT(1) NOT NULL DEFAULT 1,dependencies_json JSON NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS system_ip_rules (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,rule_type ENUM('allow','deny') NOT NULL,cidr VARCHAR(64) NOT NULL,description VARCHAR(255) NULL,enabled TINYINT(1) NOT NULL DEFAULT 1,starts_at DATETIME NULL,expires_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_system_ip_rule(rule_type,cidr));
CREATE TABLE IF NOT EXISTS system_access_policies (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,policy_key VARCHAR(120) NOT NULL UNIQUE,name VARCHAR(180) NOT NULL,description TEXT NULL,domain ENUM('SYSTEM','SCHOOL') NOT NULL,effect ENUM('allow','deny') NOT NULL DEFAULT 'deny',enabled TINYINT(1) NOT NULL DEFAULT 1,rules_json JSON NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS system_route_access_rules (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,route_key VARCHAR(190) NOT NULL,http_method VARCHAR(10) NOT NULL DEFAULT '*',domain ENUM('SYSTEM','SCHOOL') NOT NULL,permission_key VARCHAR(190) NULL,effect ENUM('allow','deny') NOT NULL DEFAULT 'deny',enabled TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_route_rule(route_key,http_method,domain));
CREATE TABLE IF NOT EXISTS system_maintenance_windows (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,message TEXT NULL,starts_at DATETIME NULL,ends_at DATETIME NULL,enabled TINYINT(1) NOT NULL DEFAULT 0,bypass_roles_json JSON NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS system_background_jobs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,queue_name VARCHAR(100) NOT NULL DEFAULT 'default',job_type VARCHAR(190) NOT NULL,payload_json JSON NULL,status ENUM('queued','running','completed','failed','retrying','cancelled') NOT NULL DEFAULT 'queued',attempts INT NOT NULL DEFAULT 0,max_attempts INT NOT NULL DEFAULT 3,available_at DATETIME NULL,started_at DATETIME NULL,completed_at DATETIME NULL,last_error TEXT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_jobs_status(status,available_at));
CREATE TABLE IF NOT EXISTS system_api_metrics (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,route_key VARCHAR(190) NOT NULL,http_method VARCHAR(10) NOT NULL,status_code SMALLINT NOT NULL,duration_ms DECIMAL(12,3) NOT NULL,user_id BIGINT NULL,ip_address VARCHAR(64) NULL,recorded_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_api_metrics_time(recorded_at),INDEX idx_api_metrics_route(route_key,http_method));
CREATE TABLE IF NOT EXISTS system_rate_limit_buckets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,bucket_key VARCHAR(190) NOT NULL UNIQUE,limit_value INT NOT NULL,window_seconds INT NOT NULL,current_count INT NOT NULL DEFAULT 0,window_started_at DATETIME NOT NULL,blocked_until DATETIME NULL,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS system_backup_runs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,backup_type ENUM('database','files','full') NOT NULL,status ENUM('queued','running','completed','failed','verified') NOT NULL DEFAULT 'queued',storage_reference VARCHAR(500) NULL,checksum VARCHAR(128) NULL,size_bytes BIGINT NULL,requested_by BIGINT NULL,started_at DATETIME NULL,completed_at DATETIME NULL,verified_at DATETIME NULL,error_message TEXT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS system_retention_policies (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,resource_key VARCHAR(190) NOT NULL UNIQUE,retention_days INT NOT NULL,action ENUM('archive','anonymize','delete') NOT NULL,enabled TINYINT(1) NOT NULL DEFAULT 1,description TEXT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS system_security_incidents (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(255) NOT NULL,severity ENUM('low','medium','high','critical') NOT NULL,status ENUM('open','investigating','contained','resolved','closed') NOT NULL DEFAULT 'open',description TEXT NULL,assigned_to BIGINT NULL,resolved_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS system_webhooks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,target_url VARCHAR(1000) NOT NULL,events_json JSON NOT NULL,enabled TINYINT(1) NOT NULL DEFAULT 1,secret_hash VARCHAR(255) NULL,secret_hint VARCHAR(20) NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS schools (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255) NOT NULL,code VARCHAR(50) NOT NULL UNIQUE,status ENUM('draft','active','suspended','archived') NOT NULL DEFAULT 'draft',created_by BIGINT NOT NULL,provisioned_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS school_provisioning_runs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,school_id BIGINT UNSIGNED NOT NULL,status ENUM('draft','in_progress','completed','failed','cancelled') NOT NULL DEFAULT 'draft',current_step INT NOT NULL DEFAULT 1,created_by BIGINT NOT NULL,completed_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_provision_school FOREIGN KEY(school_id) REFERENCES schools(id));
CREATE TABLE IF NOT EXISTS school_provisioning_steps (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,run_id BIGINT UNSIGNED NOT NULL,step_number INT NOT NULL,payload_json JSON NOT NULL,completed_by BIGINT NOT NULL,completed_at DATETIME NOT NULL,UNIQUE KEY uq_provision_step(run_id,step_number),CONSTRAINT fk_provision_step_run FOREIGN KEY(run_id) REFERENCES school_provisioning_runs(id) ON DELETE CASCADE);
COMMIT;
